#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    while(cin>>n && n){
        map<pair<int,int>,int> cnt;
        for(int i=0;i<n;i++){
            int a,b; cin>>a>>b;
            cnt[{a,b}]++;
        }
        bool ok=true;
        for(auto& kv : cnt){
            pair<int,int> rev(kv.first.second, kv.first.first);
            if(cnt[rev]!=kv.second) ok=false;
        }
        cout << (ok? "YES":"NO") << "\n";
    }
}

